  GermanWord(id: 'x21117', article: '', german: 'reagieren', plural: '—', english: 'to react; to respond', exampleGerman: 'Ich wusste nicht, wie ich reagieren sollte.', exampleEnglish: 'I didn’t know how to react.', category: 'Actions', level: 'B1'),
