  GermanWord(id: 'x21149', article: 'der', german: 'Zustand', plural: 'die Zustände', english: 'condition; state', exampleGerman: 'Der Zustand des Buchs ist nicht so gut.', exampleEnglish: 'The book’s condition isn’t so good.', category: 'General', level: 'B1'),
