  GermanWord(id: 'x21167', article: '', german: 'gebrauchen', plural: '—', english: 'to use', exampleGerman: 'Dieses Wörterbuch ist fast nicht zu gebrauchen.', exampleEnglish: 'This dictionary is nearly useless.', category: 'Actions', level: 'B1'),
  GermanWord(id: 'x21168', article: '', german: 'auftreten', plural: '—', english: 'to kick something open', exampleGerman: 'Nicht die Tür auftreten!', exampleEnglish: 'Don’t kick the door open.', category: 'Actions', level: 'B1'),
  GermanWord(id: 'x21169', article: 'der', german: 'Schutz', plural: 'die Schutze', english: 'protection', exampleGerman: 'Er nimmt ihn sehr in Schutz.', exampleEnglish: 'He’s very protective of him.', category: 'General', level: 'B1'),
  GermanWord(id: 'x21170', article: '', german: 'bestrafen', plural: '—', english: 'to punish', exampleGerman: 'Ich habe beschlossen, Sie nicht zu bestrafen.', exampleEnglish: 'I’ve decided not to punish you.', category: 'Actions', level: 'B1'),
  GermanWord(id: 'x21171', article: '', german: 'gründen', plural: '—', english: 'to found, to establish (a community, settlement, organization, company, etc.)', exampleGerman: 'Ich denke darüber nach, eine neue Firma zu gründen.', exampleEnglish: 'I’ve been thinking about starting a new business.', category: 'Actions', level: 'B1'),
