  GermanWord(id: 'x22312', article: '', german: 'unabhängig', plural: '—', english: 'independently, irrespectively, regardless', exampleGerman: 'Er ist unabhängig von seinen Eltern.', exampleEnglish: 'He is independent of his parents.', category: 'Description', level: 'B2'),
  GermanWord(id: 'x22313', article: 'der', german: 'Herzschlag', plural: 'die Herzschläge', english: 'heartbeat', exampleGerman: 'Der Arzt überwacht den Herzschlag und den Blutdruck des Patienten.', exampleEnglish: 'The doctor monitored the patient’s heartbeat and blood pressure.', category: 'General', level: 'B2'),
